Member

  Meaning






 std::size_t max_blocks_per_chunk;






  The maximum number of blocks that will be allocated at once from the upstream std::pmr::memory_resource to replenish the pool. If the value of max_blocks_per_chunk is zero or is greater than an implementation-defined limit, that limit is used instead. The implementation may choose to use a smaller value than is specified in this field and may use different values for different pools.






 std::size_t largest_required_pool_block;






 The largest allocation size that is required to be fulfilled using the pooling mechanism. Attempts to allocate a single block larger than this threshold will be allocated directly from the upstream std::pmr::memory_resource. If largest_required_pool_block is zero or is greater than an implementation-defined limit, that limit is used instead. The implementation may choose a pass-through threshold larger than specified in this field.

examples.code:
#include <memory_resource>
#include <vector>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::pmr::memory_resource *upstream = std::pmr::new_delete_resource();
    assert(upstream->is_equal(*upstream) && *upstream == *upstream);
    void *raw = upstream->allocate(16, alignof(int));
    upstream->deallocate(raw, 16, alignof(int));
    std::pmr::polymorphic_allocator<int> allocator{upstream};
    assert(allocator.resource() == upstream &&
        allocator == std::pmr::polymorphic_allocator<int>{upstream});
    int *value = allocator.allocate(1);
    allocator.construct(value, 7);
    assert(*value == 7);
    allocator.destroy(value);
    allocator.deallocate(value, 1);
    raw = allocator.allocate_bytes(32);
    allocator.deallocate_bytes(raw, 32);
    value = allocator.allocate_object<int>(2);
    allocator.deallocate_object(value, 2);
    value = allocator.new_object<int>(9);
    assert(*value == 9);
    allocator.delete_object(value);
    auto copy = allocator.select_on_container_copy_construction();
    assert(copy.resource() == std::pmr::get_default_resource());
    std::byte buffer[1024];
    std::pmr::monotonic_buffer_resource arena{buffer, sizeof buffer, upstream};
    assert(arena.upstream_resource() == upstream);
    raw = arena.allocate(16);
    arena.deallocate(raw, 16);
    arena.release();
    std::pmr::pool_options options;
    options.max_blocks_per_chunk = 8;
    std::pmr::synchronized_pool_resource shared{options, upstream};
    std::pmr::unsynchronized_pool_resource local{options, upstream};
    assert(shared.upstream_resource() == upstream &&
        local.upstream_resource() == upstream);
    assert(
        !arena.is_equal(shared) && !shared.is_equal(local) && !local.is_equal(arena));
    assert(shared.options().max_blocks_per_chunk >= 8 &&
        local.options().max_blocks_per_chunk >= 8);
    raw = shared.allocate(16);
    shared.deallocate(raw, 16);
    shared.release();
    raw = local.allocate(16);
    local.deallocate(raw, 16);
    local.release();
}
